/// Organization owner account identities with email/password credentials and
/// account lifecycle metadata.
///
/// This table stores the global authenticated identity for owner actors in
/// the HRM time tracking platform. It is intentionally limited to credential
/// and account-state information and does not duplicate organization
/// membership, workspace selection, or profile presentation data.
///
/// Owner-specific login sessions are stored in {@link
/// hrm_time_tracking_owner_sessions}, and password recovery records are
/// stored in {@link hrm_time_tracking_owner_password_resets}.
/// Organization-scoped workforce and tenant relationships are modeled in
/// other components rather than this actor table.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model hrm_time_tracking_owners {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used as the owner account login identifier.
  email String

  /// Hashed password for authenticating the owner account.
  password_hash String

  /// Timestamp of the most recent successful login for the owner account.
  last_login_at DateTime? @db.Timestamptz

  /// Timestamp when the owner account was deactivated from active use while
  /// preserving historical references.
  deactivated_at DateTime? @db.Timestamptz

  /// Timestamp when the owner account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the owner account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion of the owner account.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions hrm_time_tracking_owner_sessions[]
  passwordResets hrm_time_tracking_owner_password_resets[]
  taskHistoryActorLinks hrm_time_tracking_task_history_of_owners[]
  activityLogAttributions hrm_time_tracking_activity_log_of_owners[]

  //----
  // INDEXES
  //----
  @@unique([email])
}

