/// Historical audit records for task status transitions within a project
/// task lifecycle.
///
/// Each row captures one status change event for a single {@link
/// hrm_time_tracking_tasks} record, including the previous status, the new
/// status, the actor category that performed the change, and the business
/// timestamp when the transition occurred. This table is append-oriented and
/// preserves workflow history without duplicating task, project, or user
/// profile data.
///
/// Concrete actor ownership is intentionally normalized through dedicated
/// subtype tables rather than multiple nullable foreign keys on this table,
/// so the status-change actor can be linked to the correct existing actor
/// model while remaining compliant with the required polymorphic ownership
/// pattern.
///
/// @namespace Projects
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model hrm_time_tracking_task_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Task whose status changed. {@link hrm_time_tracking_tasks.id}.
  hrm_time_tracking_task_id String @db.Uuid

  /// Category of actor who performed the status change. Expected business
  /// values are owner, manager, or employee.
  actor_type String

  /// Task status value before the transition was applied.
  old_status String

  /// Task status value after the transition was applied.
  new_status String

  /// Business timestamp when the task status transition was made.
  changed_at DateTime @db.Timestamptz

  /// Timestamp when this audit record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this audit record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for this audit record when it is logically
  /// removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  task hrm_time_tracking_tasks @relation(fields: [hrm_time_tracking_task_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  ownerActorLink   hrm_time_tracking_task_history_of_owners?
  managerActorLink hrm_time_tracking_task_history_of_managers?
  employeeActor    hrm_time_tracking_task_history_of_employees?

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([hrm_time_tracking_task_id, changed_at], map: "hrm_time_tracking_task_histories_hrm_time_tracking_tas_b5b58c20")
  @@index([actor_type, changed_at])
}

/// Subtype record that links a task status history entry to the owner
