  /// Linked task status history record. {@link
  /// hrm_time_tracking_task_histories.id}.
  hrm_time_tracking_task_history_id String @db.Uuid

  /// Owner account that performed the task status change. {@link
  /// hrm_time_tracking_owners.id}.
  hrm_time_tracking_owner_id String @db.Uuid

  /// When this owner subtype link was created.
  created_at DateTime @db.Timestamptz

  /// When this owner subtype link was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this owner subtype link was soft deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
