  // spellchecker: ignore-next-line
  owner       hrm_time_tracking_owners         @relation(fields: [hrm_time_tracking_owner_id], references: [id], onDelete: Cascade, map: "hrm_time_tracking_task_history_of_owners_hrm_time_trac_02aa979d")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
