import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIHrmTimeTrackingManager } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmTimeTrackingManager";
