  );
  TestValidator.predicate(
    "Manager built-in role exists",
    builtInRolesPage.data.some((role) => role.name === "Manager"),
  );
  TestValidator.predicate(
    "Employee built-in role exists",
    builtInRolesPage.data.some((role) => role.name === "Employee"),
