        managerConnection,
        {
          body: grandchildBody,
        },
      );
    },
  );
  const duplicateNameBody = {
    name: topLevel.name,
    description: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IHrmTimeTrackingDepartment.ICreate;
