    name: `dept-updated-${RandomGenerator.alphabets(8)}`,
    description: RandomGenerator.paragraph({ sentences: 5 }),
    parentDepartmentId: child.id,
  } satisfies IHrmTimeTrackingDepartment.IUpdate;
