    body: {
      email: managerEmail,
      password: managerPassword,
      href,
      referrer,
    } satisfies IHrmTimeTrackingManager.ILogin,
  });
  typia.assert(loggedInManager);
  const now = new Date();
  const utcDay = now.getUTCDay();
  const diffToMonday = utcDay === 0 ? -6 : 1 - utcDay;
