  } else {
    const emptyFilterRequest = {
      search: RandomGenerator.alphaNumeric(16),
      sort: baselineRequest.sort,
      page: 1,
      limit: 10,
    } satisfies IHrmTimeTrackingReport.IRequest;
    const emptyFiltered = await api.functional.hrmTimeTracking.reports.index(
