          due_date: new Date(
            Date.now() + 1000 * 60 * 60 * 24 * (index + 5),
          ).toISOString(),
        } satisfies IHrmTimeTrackingTask.ICreate,
      },
    );
    typia.assert(task);
    return task;
  });
  const report = await generate_random_hrm_time_tracking_reports_create(
    ownerConnection,
    {
      body: {
        name: `report-${RandomGenerator.alphabets(8)}`,
        reportType: "time_report",
