          summary.organization.id,
          organizationId,
        );
      }
    }
  } catch (exp) {
    await TestValidator.httpError(
      "invalid or cross-organization project filter can be rejected",
      [400, 401, 403, 404, 422],
      async () => {
        throw exp;
      },
    );
  }
}

