import { authorize_owner_join } from "../../../authorize/authorize_owner_join";
import { authorize_owner_login } from "../../../authorize/authorize_owner_login";
import { authorize_owner_refresh } from "../../../authorize/authorize_owner_refresh";

export async function test_api_timesheet_approval_submitted_success(
  connection: api.IConnection,
): Promise<void> {
  const ownerConnection: api.IConnection = { host: connection.host };
  await authorize_owner_join(ownerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmTimeTrackingOwner.IJoin,
  });
  const approved =
    await api.functional.hrmTimeTracking.owner.timesheets.approve(
      ownerConnection,
      {
        timesheetId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  typia.assert(approved);
  const totalMinutes = approved.timelogs.reduce(
    (sum, timelog) => sum + timelog.duration_minutes,
    0,
  );
  const expectedTotalHours = totalMinutes / 60;
  TestValidator.equals("status becomes approved", approved.status, "approved");
  TestValidator.predicate(
    "reviewed_at populated after approval",
    approved.reviewed_at !== null,
  );
  TestValidator.predicate(
    "submitted_at preserved from prior submission",
    approved.submitted_at !== null,
  );
  TestValidator.equals(
    "approved record has no rejection reason",
    approved.rejection_reason,
    null,
  );
  TestValidator.equals(
    "total_hours matches summed timelog minutes",
    approved.total_hours,
    expectedTotalHours,
  );
  TestValidator.predicate(
    "all timelogs belong to same employee as timesheet",
    approved.timelogs.every(
      (timelog) => timelog.employee.id === approved.employee.id,
    ),
  );
  TestValidator.predicate(
    "all timelogs belong to same organization as timesheet",
    approved.timelogs.every(
      (timelog) => timelog.organization.id === approved.organization.id,
    ),
  );
  TestValidator.predicate(
    "reporting week boundary is ordered",
    new Date(approved.week_start_date).getTime() <=
      new Date(approved.week_end_date).getTime(),
  );
}

