  const owner = await MyGlobal.prisma.$transaction(async (tx) => {
    return await tx.hrm_time_tracking_owners.create({
      data: {
        id: ownerId,
        email: normalizedEmail,
        password_hash: await PasswordUtil.hash(normalizedPassword),
        last_login_at: nowText,
        deactivated_at: null,
        created_at: nowText,
        updated_at: nowText,
