        email: true,
        last_login_at: true,
        deactivated_at: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
  });
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "owner",
        id: owner.id,
        session_id: sessionId,
        created_at: nowText,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "owner",
        id: owner.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: nowText,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiredAtText,
    refreshable_until: refreshableUntilText,
  };
  return {
    id: owner.id,
    email: owner.email,
    last_login_at:
      owner.last_login_at !== null
