      typeof record["hrm_time_tracking_role_id"] === "string"
        ? (record["hrm_time_tracking_role_id"] as string)
        : typeof record["role_id"] === "string"
          ? (record["role_id"] as string)
          : typeof record["roleId"] === "string"
            ? (record["roleId"] as string)
            : null;
