  const whereInput = {
    hrm_time_tracking_organization_id:
      session.hrm_time_tracking_organization_id,
    deleted_at: null,
    worked_on: {
      gte: new globalThis.Date(startEpoch),
      lte: new globalThis.Date(endEpoch),
    },
