  public async search(
    @OwnerAuth()
    owner: OwnerPayload,
    @TypedBody()
    body: IHrmTimeTrackingActivityLog.IRequest,
  ): Promise<IPageIHrmTimeTrackingActivityLog.ISummary> {
    try {
      return await patchHrmTimeTrackingOwnerActivityLogsSearch({
        owner,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

